import{d as A,C as r,o as C,c as V,a3 as i,E as a,j as t,a as e}from"./chunks/framework.Q4yG9rk_.js";const E=JSON.parse('{"title":"庄子·则阳","description":"从则阳求见楚王、公阅休的处身，到圣人的爱人与命名、从师而不囿及蜗角之争，辨析交往、认识尺度与行动之间的关系。","frontmatter":{"title":"庄子·则阳","description":"从则阳求见楚王、公阅休的处身，到圣人的爱人与命名、从师而不囿及蜗角之争，辨析交往、认识尺度与行动之间的关系。","category":"guide","aliases":["则阳","庄子则阳","zhuangzi chapter 25"],"source":["《庄子·杂篇·则阳》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-25.md","filePath":"daoism/zhuang-zi/chapter-25.md","lastUpdated":1792641266000}'),D={name:"daoism/zhuang-zi/chapter-25.md"},G=A({...D,setup(I){const p=[{id:"zy_audience_s1",label:"求见未成：彭阳转问王果",sentences:[["则阳游于楚，夷节言之于王，王未之见。夷节归。"],["彭阳见王果曰：「夫子何不谭我于王？」"],["王果曰：「我不若公阅休。」"]]},{id:"zy_audience_s2",label:"公阅休的生活：江与山樊",sentences:[["彭阳曰：「公阅休奚为者邪？」"],["曰：「冬则戳鳖于江，夏则休乎山樊。有过而问者，曰：『此予宅也。』"],["夫夷节已不能，而况我乎！吾又不若夷节。"]]},{id:"zy_audience_s3",label:"夷节的交往：相助还是相消",sentences:[["夫夷节之为人也，无德而有知，不自许，以之神其交，固颠冥乎富贵之地。"],["非相助以德，相助消也。"],["夫冻者假衣于春，暍者反冬乎冷风。"]]},{id:"zy_audience_s4",label:"楚王严厉：谁能使其改变",sentences:[["夫楚王之为人也，形尊而严。其于罪也，无赦如虎。"],["非夫",{text:"佞人正德",glossary:"zy_audience_ningde"},"，其孰能桡焉。"]]},{id:"zy_audience_s5",label:"圣人的穷达：相通而保己",sentences:[["故圣人其穷也，使家人忘其贫；其达也，使王公忘爵禄而化卑；"],["其于物也，与之为娱矣；其于人也，乐物之通而保己焉。"]]},{id:"zy_audience_s6",label:"不言饮和：回到公阅休",sentences:[["故或不言而饮人以和，与人并立而使人化，父子之宜。"],["彼其乎归居，而一闲其所施。其于人心者，若是其远也。"],["故曰『待公阅休』。」"]]}],o=[{id:"zy_audience_people",term:"则阳、彭阳、夷节、王果、公阅休",pinyin:"zé yáng、péng yáng、yí jié、wáng guǒ、gōng yuè xiū",meaning:"篇中人物。彭阳通常联系则阳理解；夷节为引荐者，王果为答话者，公阅休由其叙述。具体官职、籍贯与历史身份不在此坐实。"},{id:"zy_audience_tan",term:"谭我于王",pinyin:"tán wǒ yú wáng",meaning:"向王谈及、介绍我，谭联系谈理解。王未之见指尚未见他，不直接断定已永久拒绝。"},{id:"zy_audience_chuobie",term:"戳鳖、山樊",pinyin:"chuō biē、shān fán",meaning:"戳鳖涉及刺取、捕取鳖，字形与读法须依底本统一，来稿注音 zhuō 不直接沿用。山樊联系山边、山林边际理解。"},{id:"zy_audience_zixu",term:"不自许，以之神其交",pinyin:"bù zì xǔ, yǐ zhī shén qí jiāo",meaning:"自许、之、神的句法与所指有解释空间。不只按表面谦虚理解，也不直接定为现代意义的神化人脉。"},{id:"zy_audience_dianming",term:"颠冥乎富贵之地、相助消",pinyin:"diān míng hū fù guì zhī dì、xiāng zhù xiāo",meaning:"沉迷、昏惑于富贵，与相互消损的交往相接。批评具体处身方式，不宣判所有引荐与互助都错误。"},{id:"zy_audience_dongye",term:"冻者假衣于春，暍者反冬乎冷风",pinyin:"dòng zhě jiǎ yī yú chūn, yē zhě fǎn dōng hū lěng fēng",meaning:"暍指暑热所困、中暑等。春、冬、假、反及整句譬喻有不同解释，不能只补成春天尚未来、向冬天求风的错误求助故事。"},{id:"zy_audience_ningde",term:"佞人正德、桡",pinyin:"nìng rén zhèng dé、náo",meaning:"佞可联系口才、善言，也有其他训法；正德及句中关系有争议。不能仅以或字拆成巧言者与正德者两类。桡联系挠、使屈转理解，音读依注本统一。"},{id:"zy_audience_yinhe",term:"饮人以和",pinyin:"yìn rén yǐ hé",meaning:"使人饮和，以饮作使动表达。写相处的感化效果，不解释成已证实的气场或神秘能量。"},{id:"zy_audience_guiju",term:"父子之宜、彼其乎归居、一闲其所施",pinyin:"fù zǐ zhī yí、bǐ qí hū guī jū、yī xián qí suǒ shī",meaning:"父子合宜、归居与施为闲静等，具体句读、代词所指有解释空间。不补成无须照料教育的完美家庭关系。"}],h=[{id:"zy_nature_s1",label:"通达与性：人从而命名",sentences:[["圣人达绸缪，周尽一体矣，而不知其然，性也。"],["复命摇作而以天为师，人则从而命之也。"],["忧乎知，而所行恒无几时，其有止也，若之何！"]]},{id:"zy_nature_s2",label:"生而美者：自知与可喜",sentences:[["生而美者，人与之鉴，不告则不知其美于人也。"],["若知之，若不知之，若闻之，若不闻之，其可喜也终无已，"],["人之好之亦无已，性也。"]]},{id:"zy_nature_s3",label:"圣人爱人：名声与实际相处",sentences:[["圣人之爱人也，人与之名，不告则不知其爱人也。"],["若知之，若不知之，若闻之，若不闻之，其爱人也终无已，"],["人之安之亦无已，性也。"]]},{id:"zy_nature_s4",label:"旧国旧都：望见与感受",sentences:[["旧国旧都，望之畅然。虽使丘陵草木之缗入之者十九，犹之畅然，"],["况见见闻闻者也，以十仞之台县众间者也。"]]},{id:"zy_nature_s5",label:"环中与随成：化与不化",sentences:[["冉相氏得其环中以随成，与物无终无始，无几无时。"],["日与物化者，一不化者也。阖尝舍之！"]]},{id:"zy_nature_s6",label:"师天的限制：与世偕行",sentences:[["夫师天而不得师天，与物皆殉。其以为事也，若之何！"],["夫圣人未始有天，未始有人，未始有始，未始有物，"],["与世偕行而不替，所行之备而不洫，其合之也，若之何！"]]}],u=[{id:"zy_nature_choumou",term:"达绸缪、周尽一体",pinyin:"dá chóu móu、zhōu jìn yī tǐ",meaning:"通达交结、深微关系，周遍而一体等，具体训释有差异。不仅凭一体二字认定已提出物理世界完全同一的理论。"},{id:"zy_nature_fuming",term:"复命摇作、忧乎知",pinyin:"fù mìng yáo zuò、yōu hū zhī",meaning:"复命、摇作与忧、知的句法有讨论空间。暂保留字面与上下文，不直接建立回归本性后完全无需思考的程序。"},{id:"zy_nature_jianming",term:"人与之鉴、人与之名",pinyin:"rén yǔ zhī jiàn、rén yǔ zhī míng",meaning:"他人给予镜鉴、名称或评价。以美与爱人的并置，区分实际表现和对表现的命名。"},{id:"zy_nature_min",term:"缗入之者十九、见见闻闻、县众间",pinyin:"mín rù zhī zhě shí jiǔ、jiàn jiàn wén wén、xuán zhòng jiān",meaning:"缗涉及遮蔽、混合等解释，十九通常联系十分之九；见见闻闻与县众间的句法所指有差异。县联系悬理解。不把整段直接坐实为本源永恒不变的证明。"},{id:"zy_nature_huanzhong",term:"冉相氏、环中、随成",pinyin:"rǎn xiāng shì、huán zhōng、suí chéng",meaning:"冉相氏为古代传说人物；环中可与《齐物论》道枢之论对读。随成涉及随顺而成，不等于不需学习与实践。"},{id:"zy_nature_buhua",term:"日与物化者，一不化者也",pinyin:"rì yǔ wù huà zhě, yī bù huà zhě yě",meaning:"化与不化并置，一的句法与哲学意义有解释空间。可讨论变化中的持续性，不直接定为人体内存在永恒实体。"},{id:"zy_nature_he",term:"阖尝舍之、与物皆殉",pinyin:"hé cháng shě zhī、yǔ wù jiē xùn",meaning:"阖有何不等解释；之所指待辨。殉可联系逐物、为物所牵等。不直接补成只有刻意师天这一种原因导致失道。"},{id:"zy_nature_weishi",term:"未始有天、未始有人、未始有始、未始有物",pinyin:"wèi shǐ yǒu tiān、wèi shǐ yǒu rén、wèi shǐ yǒu shǐ、wèi shǐ yǒu wù",meaning:"限制将天、人、始、物固定建立为分别对象的方式等，有不同解释。不仅指词汇或概念从未出现在脑中，也不是现实不存在人和物。"},{id:"zy_nature_xu",term:"不替、不洫、若之何",pinyin:"bù tì、bù xù、ruò zhī hé",meaning:"替有废、衰等义，洫有损耗等解释，不只作溢出越界。若之何是反问、感叹或追问式表达，不能自动等同作者因无法言说而故意不给答案。"}],g=[{id:"zy_learning_s1",label:"汤与司御：从师而不囿",sentences:[["汤得其司御，门尹登恒为之傅之。"],["从师而不囿，得其随成。"]]},{id:"zy_learning_s2",label:"名、法与两见：疑难文字",sentences:[["为之司其名之名嬴法得其两见。仲尼之尽虑，为之傅之。"]]},{id:"zy_learning_s3",label:"容成氏之言：日岁与内外",sentences:[["容成氏曰：「除日无岁，无内无外。」"]]}],y=[{id:"zy_learning_siyu",term:"司御、门尹登恒、傅",pinyin:"sī yù、mén yǐn dēng héng、fù",meaning:"涉及御者、官名或人物及辅导、师傅等，句间人物关系须依注本核对。不补成身份完全确定的近侍与老师名单。"},{id:"zy_learning_buyou",term:"从师而不囿，得其随成",pinyin:"cóng shī ér bù yòu, dé qí suí chéng",meaning:"从师而不被圈限，随顺而成。可保留学习与不囿并存，不直接推出学习无必要或任何训练都违背本性。"},{id:"zy_learning_yingfa",term:"为之司其名之名嬴法得其两见",pinyin:"wéi zhī sī qí míng zhī míng yíng fǎ dé qí liǎng jiàn",meaning:"本段疑难文字，句读、字形与所指不宜强定。暂不将其确定译为掌管名分、法度圆满而兼顾两面。"},{id:"zy_learning_zhongni",term:"仲尼之尽虑，为之傅之",pinyin:"zhòng ní zhī jìn lǜ, wéi zhī fù zhī",meaning:"与前句关系存在讨论空间。不仅据傅字补成孔子从这件事受教的完整故事。"},{id:"zy_learning_rongcheng",term:"容成氏、除日无岁、无内无外",pinyin:"róng chéng shì、chú rì wú suì、wú nèi wú wài",meaning:"容成氏见古代传说，具体身份不坐实。日与岁、内与外的关系可作概念辨析，但不能由短句推出所有整体都是虚假、只有微小单位真实。"}],m=[{id:"zy_snail_s1",label:"背约与报复：公孙衍请战",sentences:[["魏莹与田侯牟约，田侯牟背之，魏莹怒，将使人剌之。"],["犀首公孙衍闻而耻之，曰：「君为万乘之君也，而以匹夫从仇。"],["衍请受甲二十万，为君攻之，虏其人民，系其牛马，使其君内热发于背，然后拔其国。"],["忌也出走，然后抶其背，折其脊。」"]]},{id:"zy_snail_s2",label:"季子反对：休兵之基",sentences:[["季子闻而耻之，曰：「筑十仞之城，城者既十仞矣，则又坏之，此胥靡之所苦也。"],["今兵不起七年矣，此王之基也。衍，乱人也，不可听也。」"]]},{id:"zy_snail_s3",label:"华子回看评判：求其道",sentences:[["华子闻而丑之，曰：「善言伐齐者，乱人也；善言勿伐者，亦乱人也；"],["谓『伐之与不伐乱人也』者，又乱人也。」"],["君曰：「然则若何？」曰：「君求其道而已矣。」"]]},{id:"zy_snail_s4",label:"戴晋人述蜗角两国",sentences:[["惠之闻之，而见戴晋人。戴晋人曰：「有所谓蜗者，君知之乎？」曰：「然。」"],["「有国于蜗之左角者，曰触氏；有国于蜗之右角者，曰蛮氏。"],["时相与争地而战，伏尸数万，逐北旬有五日而后反。」"],["君曰：「噫！其虚言与？」"]]},{id:"zy_snail_s5",label:"游心无穷：反观魏、梁与王",sentences:[["曰：「臣请为君实之。君以意在四方上下有穷乎？」君曰：「无穷。」"],["曰：「知游心于无穷，而反在通达之国，若存若亡乎？」君曰：「然。」"],["曰：「通达之中有魏，于魏中有梁，于梁中有王，王与蛮氏有辩乎？」"],["君曰：「无辩。」"]]},{id:"zy_snail_s6",label:"君王的反应：若有所失",sentences:[["客出而君惝然若有亡也。客出，惠子见。"],["君曰：「客，大人也，圣人不足以当之。」"]]},{id:"zy_snail_s7",label:"惠子作比：剑首之吷",sentences:[["惠子曰：「夫吹管也，犹有嗃也；吹剑首者，吷而已矣。"],["尧、舜，人之所誉也。道尧、舜于戴晋人之前，譬犹一吷也。」"]]}],b=[{id:"zy_snail_people",term:"魏莹、田侯牟、公孙衍、季子、华子",pinyin:"wèi yíng、tián hóu móu、gōng sūn yǎn、jì zǐ、huá zǐ",meaning:"篇中君主与进言者。魏莹通常联系魏惠王，田侯牟的历史对应及字形须依注本核对，不直接坐实为名牟的齐威王。寓言不等于严格的外交纪事。"},{id:"zy_snail_ci",term:"剌之、万乘、受甲",pinyin:"cì zhī、wàn shèng、shòu jiǎ",meaning:"剌在此联系刺理解，最终核对字形；乘在万乘读 shèng；受甲涉及领受、率领甲兵。来稿万乘注音 chéng 不沿用。"},{id:"zy_snail_chi",term:"抶、胥靡",pinyin:"chì、xū mí",meaning:"抶指击打；胥靡涉及服役、受刑役者。筑而复坏的譬喻关注劳役代价，不只关注君主成果。"},{id:"zy_snail_luanren",term:"善言伐、善言勿伐、谓皆乱人者",pinyin:"shàn yán fá、shàn yán wù fá、wèi jiē luàn rén zhě",meaning:"递次回看主张和评判本身。不能把第三层宣布成永远正确的框架外立场，也不直接证明战争与和平后果完全一样。"},{id:"zy_snail_huizhi",term:"惠之闻之、戴晋人",pinyin:"huì zhī wén zhī、dài jìn rén",meaning:"前句通常联系惠子引见理解，惠之字形、句读最终依底本处理。戴晋人的具体历史身份不在此坐实。"},{id:"zy_snail_zhubei",term:"逐北旬有五日",pinyin:"zhú běi xún yòu wǔ rì",meaning:"追逐败逃者十五日。北指败逃，有联系又理解。是蜗角故事中的夸张叙述。"},{id:"zy_snail_bian",term:"王与蛮氏有辩乎",pinyin:"wáng yǔ mán shì yǒu biàn hū",meaning:"辩联系辨、区别理解。通过尺度转换比较，不证明两者的具体处境、责任与伤亡完全相同。"},{id:"zy_snail_changran",term:"惝然若有亡",pinyin:"chǎng rán ruò yǒu wáng",meaning:"怅惘、失神，若有所失。原文没有具体说失去报复心，不补成君主已彻底完成转变。"},{id:"zy_snail_hexue",term:"嗃、剑首、吷",pinyin:"hè、jiàn shǒu、xuè",meaning:"嗃涉及声音，具体音义依注本统一；剑首通常联系剑柄端孔；吷指微声。不是以声音短小直接证明言说更接近本质。"}],c=[{id:"zy_hidden_s1",label:"投宿蚁丘：子路问邻人",sentences:[["孔子之楚，舍于蚁丘之浆。其邻有夫妻臣妾登极者，"],["子路曰：「是稯稯何为者邪？」"]]},{id:"zy_hidden_s2",label:"仲尼描述：自埋、自藏与陆沉",sentences:[["仲尼曰：「是圣人仆也。是自埋于民，自藏于畔。"],["其声销，其志无穷，其口虽言，其心未尝言。"],["方且与世违，而心不屑与之俱。是陆沉者也，是其市南宜僚邪？」"]]},{id:"zy_hidden_s3",label:"子路请召：孔子推测对方的看法",sentences:[["子路请往召之。孔子曰：「已矣！"],["彼知丘之著于己也，知丘之适楚也，以丘为必使楚王之召己也。"],["彼且以丘为佞人也。"]]},{id:"zy_hidden_s4",label:"羞见佞人：子路所见为空室",sentences:[["夫若然者，其于佞人也，羞闻其言，而况亲见其身乎！而何以为存！」"],["子路往视之，其室虚矣。"]]}],_=[{id:"zy_hidden_she",term:"舍于蚁丘之浆",pinyin:"shè yú yǐ qiū zhī jiāng",meaning:"舍指投宿，蚁丘通常作地名理解，浆可联系卖浆者或其处所。不直接补定为售酒的现代店铺。"},{id:"zy_hidden_dengji",term:"夫妻臣妾登极、稯稯",pinyin:"fū qī chén qiè dēng jí、zōng zōng",meaning:"夫妻、臣妾及登极的关系与所指有不同解释；稯稯写聚集等状态。不仅定为全家登屋避暑或劳作，具体目的原文未交代。"},{id:"zy_hidden_shengrenpu",term:"圣人仆",pinyin:"shèng rén pú",meaning:"仆的用法及其与后文所述者的关系有解释空间。不仅据此确定邻家藏着一位圣人、眼前人全是其仆役。"},{id:"zy_hidden_shengxiao",term:"其声销、其志无穷",pinyin:"qí shēng xiāo、qí zhì wú qióng",meaning:"名声消隐而志不穷等。销联系消隐理解，不将其定为没有任何社会联系。"},{id:"zy_hidden_xinyan",term:"其口虽言，其心未尝言",pinyin:"qí kǒu suī yán, qí xīn wèi cháng yán",meaning:"口言与心未尝言形成反常对照，可联系不以言说争立、不让心受说辩牵引等理解，不只定为故意隐藏秘密真意。"},{id:"zy_hidden_luchen",term:"陆沉",pinyin:"lù chén",meaning:"以在陆而沉的反常意象写处世隐没。不直接等同后世大隐隐于市的固定境界等级。"},{id:"zy_hidden_yiliao",term:"是其市南宜僚邪",pinyin:"shì qí shì nán yí liáo yé",meaning:"对身份的疑问、推测。可与《徐无鬼》市南宜僚故事对读，但不将疑问句改成已经确认的身份。"},{id:"zy_hidden_zhuziji",term:"彼知丘之著于己也",pinyin:"bǐ zhī qiū zhī zhù yú jǐ yě",meaning:"著及己的所指、句法有讨论空间，可涉及孔子对其知晓、显明等关系。不仅定为对方知道孔子自身名声显扬。"},{id:"zy_hidden_ningren",term:"佞人、何以为存",pinyin:"nìng rén、hé yǐ wéi cún",meaning:"佞人可联系巧言、说进之人；何以为存追问对方为何还会留下。是孔子推测对方看法，不等于作者直接给孔子判定谄媚人格。"}],z=[{id:"zy_cultivation_s1",label:"为政治民：勿卤莽、勿灭裂",sentences:[["长梧封人问子牢曰：「君为政焉勿卤莽，治民焉勿灭裂。"]]},{id:"zy_cultivation_s2",label:"治禾经验：改变耕作方式",sentences:[["昔予为禾，耕而卤莽之，则其实亦卤莽而报予；"],["芸而灭裂之，其实亦灭裂而报予。"],["予来年变齐，深其耕而熟耰之，其禾蘩以滋，予终年厌飧。」"]]},{id:"zy_cultivation_s3",label:"庄子转论身心：遁天、离性",sentences:[["庄子闻之曰：「今人之治其形，理其心，多有似封人之所谓："],["遁其天，离其性，灭其情，亡其神，以众为。"]]},{id:"zy_cultivation_s4",label:"欲恶与杂草：卤莽其性",sentences:[["故卤莽其性者，欲恶之孽为性，萑苇蒹葭始萌，"],["以扶吾形，寻擢吾性。"]]},{id:"zy_cultivation_s5",label:"疮病之喻：溃漏与内热",sentences:[["并溃漏发，不择所出，漂疽疥癕，内热溲膏是也。」"]]}],x=[{id:"zy_cultivation_people",term:"长梧封人、子牢",pinyin:"cháng wú fēng rén、zǐ láo",meaning:"封人涉及疆界、封域等职掌；长梧通常作地名理解。子牢身份不在此坐实为孔子某位弟子。"},{id:"zy_cultivation_lumang",term:"卤莽、灭裂",pinyin:"lǔ mǎng、miè liè",meaning:"粗疏草率、马虎不周等，与耕作回报及治民相接。不等于一切积极作为。"},{id:"zy_cultivation_yunyou",term:"芸、熟耰、蘩以滋",pinyin:"yún、shú yōu、fán yǐ zī",meaning:"芸联系耘、除草；耰涉及耙土、覆土等耕作；蘩以滋写茂盛滋长。原文肯定改进与细致照料，不只主张停止干预。"},{id:"zy_cultivation_bianqi",term:"变齐、厌飧",pinyin:"biàn qí、yàn sūn",meaning:"变齐涉及改变方法、调节等，齐的具体训释与读法依注本统一；厌联系饱足，飧为饭食。不作现代产量保证。"},{id:"zy_cultivation_tianxing",term:"遁其天、离其性、灭其情、亡其神",pinyin:"dùn qí tiān、lí qí xìng、miè qí qíng、wáng qí shén",meaning:"并列写天、性、情、神受到损害等，具体训释有空间。不直接定为四级损害次序，也不把情只译作现代情绪。"},{id:"zy_cultivation_zhongwei",term:"以众为、欲恶之孽为性",pinyin:"yǐ zhòng wéi、yù wù zhī niè wéi xìng",meaning:"众为、为性的句法与所指需辨，可联系繁多施为、欲恶滋生等。不能先宣布所有欲望与厌恶都不属于人的本性。"},{id:"zy_cultivation_huanwei",term:"萑苇蒹葭、扶形、寻擢",pinyin:"huán wěi jiān jiā、fú xíng、xún zhuó",meaning:"芦苇类植物与扶、擢的组合构成耕作比喻，具体字义有差异。不仅把扶定为看似帮助实则侵占，或把擢只定为拔除本性。"},{id:"zy_cultivation_bing",term:"漂疽疥癕、内热溲膏",pinyin:"piāo jū jiè yōng、nèi rè sōu gāo",meaning:"涉及疮病、内热与排泄异常等古代病象，漂等音义待底本核对。不直接对应现代确诊疾病，也不作为性情导致疾病的医学证据。"}],q=[{id:"zy_responsibility_s1",label:"柏矩请游：始于齐",sentences:[["柏矩学于老聃，曰：「请之天下游。」"],["老聃曰：「已矣！天下犹是也。」"],["又请之，老聃曰：「汝将何始？」曰：「始于齐。」"]]},{id:"zy_responsibility_s2",label:"见辜人：覆盖与哭号",sentences:[["至齐，见辜人焉，推而强之，解朝服而幕之，号天而哭之，"],["曰：「子乎！子乎！天下有大灾，子独先离之。"]]},{id:"zy_responsibility_s3",label:"病与争：不只发布禁令",sentences:[["曰『莫为盗，莫为杀人』。荣辱立然后睹所病，货财聚然后睹所争。"],["今立人之所病，聚人之所争，穷困人之身，使无休时。欲无至此得乎？"]]},{id:"zy_responsibility_s4",label:"古之君人者：退而自责",sentences:[["古之君人者，以得为在民，以失为在己；以正为在民，以枉为在己。"],["故一形有失其形者，退而自责。"]]},{id:"zy_responsibility_s5",label:"今之为政：设难而责不能",sentences:[["今则不然，匿为物而愚不识，大为难而罪不敢，"],["重为任而罚不胜，远其涂而诛不至。"]]},{id:"zy_responsibility_s6",label:"知力竭：伪、欺、盗的追问",sentences:[["民知力竭，则以伪继之。日出多伪，士民安取不伪。"],["夫力不足则伪，知不足则欺，财不足则盗。"],["盗窃之行，于谁责而可乎？」"]]}],f=[{id:"zy_responsibility_boju",term:"柏矩、老聃",pinyin:"bó jǔ、lǎo dān",meaning:"篇中师生人物。柏的音读依注本统一，不据故事直接复原历史师承。"},{id:"zy_responsibility_youshi",term:"天下犹是也",pinyin:"tiān xià yóu shì yě",meaning:"天下仍如此等，可联系处境未改理解。不直接定为任何地方完全相同、游历永远无益。"},{id:"zy_responsibility_guren",term:"辜人、推而强之、幕之",pinyin:"gū rén、tuī ér qiǎng zhī、mù zhī",meaning:"辜人涉及受罪刑、遭刑而陈尸者，具体刑式不在此坐实；推强可联系扶整、伸直；幕为覆盖。强的音义依注本统一。"},{id:"zy_responsibility_li",term:"子独先离之",pinyin:"zǐ dú xiān lí zhī",meaning:"离可联系罹、遭遇理解。把个体遭难置于天下之灾中，不证明任何人在同样条件下都必然有同一结局。"},{id:"zy_responsibility_xingshi",term:"一形有失其形者",pinyin:"yī xíng yǒu shī qí xíng zhě",meaning:"形及失其形有不同解释，可能涉及身体、生命与处身受损。不只定为失去本分或犯罪。"},{id:"zy_responsibility_nanni",term:"匿为物、大为难、重为任、远其涂",pinyin:"nì wéi wù、dà wéi nán、zhòng wéi rèn、yuǎn qí tú",meaning:"并列描写隐难、艰难、重负与远途等条件，再责罚未达者。匿的具体训释需辨，不直接补成所有要求皆为故意设置的不可能陷阱。"},{id:"zy_responsibility_sheng",term:"罚不胜、民知力竭",pinyin:"fá bù shèng、mín zhì lì jié",meaning:"胜在承受、胜任义读 shèng；知可联系智，与力并列。不仅译作每个百姓的智力都低下。"},{id:"zy_responsibility_weidao",term:"力不足则伪、知不足则欺、财不足则盗",pinyin:"lì bù zú zé wěi、zhì bù zú zé qī、cái bù zú zé dào",meaning:"以强烈概括说明压力下的应付、欺诈与盗窃，意在追问责任。不作为贫困者必犯罪的经验定律，也不使伤害行为自动正当。"}],k=[{id:"zy_revision_s1",label:"六十而六十化：始是而卒非",sentences:[["蘧伯玉行年六十而六十化，未尝不始于是之，而卒诎之以非也。"],["未知今之所谓是之非五十九非也。"]]},{id:"zy_revision_s2",label:"生与出：根门未见",sentences:[["万物有乎生而莫见其根，有乎出而莫见其门。"]]},{id:"zy_revision_s3",label:"所知与所不知：大疑",sentences:[["人皆尊其知之所知，而莫知恃其知之所不知而后知，"],["可不谓大疑乎！"]]},{id:"zy_revision_s4",label:"无所逃：然与然的疑难",sentences:[["已乎！已乎！且无所逃。此所谓然与然乎！"]]}],P=[{id:"zy_revision_quboyu",term:"蘧伯玉、六十化",pinyin:"qú bó yù、liù shí huà",meaning:"蘧伯玉见相关古代记载；本段以六十化写不断变化修正。不是精确列出每年一次、共六十项认知记录。"},{id:"zy_revision_qu",term:"始于是之，卒诎之以非",pinyin:"shǐ yú shì zhī, zú qū zhī yǐ fēi",meaning:"开始认其为是，最终以非屈退、否定之。诎联系屈理解。对自身判断的回看，不等于每一项知识都必定错误。"},{id:"zy_revision_wushijiu",term:"未知今之所谓是之非五十九非也",pinyin:"wèi zhī jīn zhī suǒ wèi shì zhī fēi wǔ shí jiǔ fēi yě",meaning:"是、非的句法有讨论空间，可把握今之所是仍需回看，不强行列为第六十次必将被否定的预报。"},{id:"zy_revision_genmen",term:"莫见其根、莫见其门",pinyin:"mò jiàn qí gēn、mò jiàn qí mén",meaning:"万物生出而其根门未见，提示所见不能穷尽来源。不证明所有来源永不可研究。"},{id:"zy_revision_shibuzhi",term:"恃其知之所不知而后知",pinyin:"shì qí zhī zhī suǒ bù zhī ér hòu zhī",meaning:"认识有赖于尚未被认识的条件、范围等，亦可引申认识自身局限。不只等于承认不知便自动获得真知。"},{id:"zy_revision_ran",term:"已乎、无所逃、然与然",pinyin:"yǐ hū、wú suǒ táo、rán yǔ rán",meaning:"感叹与疑问式收束，末句音义、句法有不同解释。不把语气确定为绝望或释然，也不只译成此时如此与彼时如此的两项叠加。"}],w=[{id:"zy_posthumous_s1",label:"仲尼问灵公之名",sentences:[["仲尼问于大史大弢、伯常骞、狶韦曰："],["「夫卫灵公饮酒湛乐，不听国家之政；田猎毕弋，不应诸侯之际："],["其所以为灵公者何邪？」"]]},{id:"zy_posthumous_s2",label:"大弢之答：是因是也",sentences:[["大弢曰：「是因是也。」"]]},{id:"zy_posthumous_s3",label:"伯常骞之答：放纵与敬肃",sentences:[["伯常骞曰：「夫灵公有妻三人，同滥而浴。"],["史鳅奉御而进所，搏币而扶翼。"],["其慢若彼之甚也，见贤人若此其肃也，是其所以为灵公也。」"]]},{id:"zy_posthumous_s4",label:"狶韦之答：卜葬与古墓",sentences:[["狶韦曰：「夫灵公也，死，卜葬于故墓，不吉；卜葬于沙丘而吉。"],["掘之数仞，得石槨焉，洗而视之，有铭焉，"],["曰：『不冯其子，灵公夺而里之。』"]]},{id:"zy_posthumous_s5",label:"狶韦评前两答",sentences:[["夫灵公之为灵也久矣！之二人何足以识之。」"]]}],T=[{id:"zy_posthumous_people",term:"大史大弢、伯常骞、狶韦",pinyin:"tài shǐ dà tāo、bó cháng qiān、xī wéi",meaning:"篇中答问人物。大史联系太史理解；不将三人的官职、籍贯与历史身份一概坐实。"},{id:"zy_posthumous_ling",term:"灵、是因是也",pinyin:"líng、shì yīn shì yě",meaning:"灵在谥法与叙事中有不同含义，不先定为纯粹美谥。是因是也可联系正因上述行迹而称灵等理解，不必直接判为答非所问。"},{id:"zy_posthumous_zhan",term:"湛乐、毕弋、诸侯之际",pinyin:"zhàn lè、bì yì、zhū hóu zhī jì",meaning:"湛涉及沉溺、深乐等，音义依注本统一；毕联系捕鸟之网；弋为系绳之箭射取；际涉及交接往来。"},{id:"zy_posthumous_lan",term:"同滥而浴、搏币而扶翼",pinyin:"tóng làn ér yù、bó bì ér fú yì",meaning:"滥可联系浴器理解；搏币、扶翼及动作主体需依注本辨析。可保留礼仪性的相迎，不强行补出所有动作细节。"},{id:"zy_posthumous_shiqiu",term:"史鳅、慢、肃",pinyin:"shǐ qiū、màn、sù",meaning:"史鳅通常联系史鱼理解。慢写放纵、简慢等，肃写敬肃；慢不直接等于怠慢妻子，也不据此建立私德与公德的完整分类。"},{id:"zy_posthumous_guo",term:"石槨、不冯其子、夺而里之",pinyin:"shí guǒ、bù píng qí zǐ、duó ér lǐ zhī",meaning:"槨为棺外套具；冯联系凭、依恃；里有葬等解释。铭文代词与句法保留说明，神异叙事不作为真实预言证据。"}],j=[{id:"zy_discourse_s1",label:"丘里之言：合异与散同",sentences:[["少知问于大公调曰：「何谓丘里之言？」"],["大公调曰：「丘里者，合十姓百名而为风俗也，合异以为同，散同以为异。"],["今指马之百体而不得马，而马系于前者，立其百体而谓之马也。"],["是故丘山积卑而为高，江河合水而为大，大人合并而为公。"]]},{id:"zy_discourse_s2",label:"殊而不私：岁成、国治与无为",sentences:[["是以自外入者，有主而不执；由中出者，有正而不距。"],["四时殊气，天不赐，故岁成；五官殊职，君不私，故国治；"],["文武殊材，大人不赐，故德备；万物殊理，道不私，故无名。"],["无名故无为，无为而无不为。"]]},{id:"zy_discourse_s3",label:"变化与相容：丘里之言的收束",sentences:[["时有终始，世有变化，祸福淳淳，至有所拂者而有所宜，自殉殊面；"],["有所正者有所差，比于大泽，百材皆度；观于大山，木石同坛。"],["此之谓丘里之言。」"]]},{id:"zy_discourse_s4",label:"称道是否足够：名称与所指",sentences:[["少知曰：「然则谓之道足乎？」"],["大公调曰：「不然，今计物之数，不止于万，而期曰万物者，以数之多者号而读之也。"],["是故天地者，形之大者也；阴阳者，气之大者也；道者为之公。"],["因其大以号而读之则可也，已有之矣，乃将得比哉！"],["则若以斯辩，譬犹狗马，其不及远矣。」"]]},{id:"zy_discourse_s5",label:"万物何起：相代与相成",sentences:[["少知曰：「四方之内，六合之里，万物之所生恶起？」"],["大公调曰：「阴阳相照相盖相治，四时相代相生相杀。"],["欲恶去就，于是桥起。雌雄片合，于是庸有。"],["安危相易，祸福相生，缓急相摩，聚散以成。"]]},{id:"zy_discourse_s6",label:"可纪与议止：言知所至",sentences:[["此名实之可纪，精之可志也。随序之相理，桥运之相使，穷则反，终则始，此物之所有。"],["言之所尽，知之所至，极物而已。"],["睹道之人，不随其所废，不原其所起，此议之所止。」"]]},{id:"zy_discourse_s7",label:"两家之议：莫为与或使",sentences:[["少知曰：「季真之莫为，接子之或使。二家之议，孰正于其情，孰偏于其理？」"],["大公调曰：「鸡鸣狗吠，是人之所知。"],["虽有大知，不能以言读其所自化，又不能以意其所将为。"],["斯而析之，精至于无伦，大至于不可围。"]]},{id:"zy_discourse_s8",label:"实与虚：未免于物",sentences:[["或之使，莫之为，未免于物而终以为过。"],["或使则实，莫为则虚。有名有实，是物之居；无名无实，在物之虚。"],["可言可意，言而愈疏。"],["未生不可忌，已死不可阻。死生非远也，理不可睹。"],["或之使，莫之为，疑之所假。"]]},{id:"zy_discourse_s9",label:"本末无穷：道之名与物之一曲",sentences:[["吾观之本，其往无穷；吾求之末，其来无止。"],["无穷无止，言之无也，与物同理。或使莫为，言之本也。与物终始。"],["道不可有，有不可无。道之为名，所假而行。"],["或使莫为，在物一曲，夫胡为于大方！"]]},{id:"zy_discourse_s10",label:"篇末：言默不足以载",sentences:[["言而足，则终日言而尽道；言而不足，则终日言而尽物。"],["道，物之极，言默不足以载。非言非默，议有所极。」"]]}],v=[{id:"zy_discourse_people",term:"少知、大公调、季真、接子",pinyin:"shǎo zhī、tài gōng tiáo、jì zhēn、jiē zǐ",meaning:"篇中问答人物及被提及的论者。名字可以作寓意阅读，但不坐实全为虚构，也不据名称确定完整学说与历史身份。"},{id:"zy_discourse_qiuli",term:"丘里之言、十姓百名",pinyin:"qiū lǐ zhī yán、shí xìng bǎi míng",meaning:"乡里及其共同风俗之言，十姓百名写众多不同者。不直接作为确切人口统计。"},{id:"zy_discourse_baiti",term:"马之百体、立其百体",pinyin:"mǎ zhī bǎi tǐ、lì qí bǎi tǐ",meaning:"马的各部与其成立为马的关系。部分不能单独替代整体，不证明整体只是虚假名称。"},{id:"zy_discourse_gong",term:"合并而为公、有主而不执、有正而不距",pinyin:"hé bìng ér wéi gōng、yǒu zhǔ ér bù zhí、yǒu zhèng ér bù jù",meaning:"合并、主、正的所指有解释空间；距联系拒理解。可讨论容纳差异，不只等同汇总意见或现代民主决策。"},{id:"zy_discourse_buci",term:"殊、不赐、不私",pinyin:"shū、bù cì、bù sī",meaning:"殊为不同；不赐在此有不偏施等解释，与不私相接。不能仅按现代不给予理解成不提供资源。"},{id:"zy_discourse_chunchun",term:"祸福淳淳、自殉殊面、百材皆度、木石同坛",pinyin:"huò fú chún chún、zì xùn shū miàn、bǎi cái jiē dù、mù shí tóng tán",meaning:"涉及祸福往来、不同趋向与共同处所等，度、坛的细义及读音须依注本统一。不推出各物都已有明确工具用途。"},{id:"zy_discourse_haodu",term:"期曰万物、号而读之",pinyin:"qī yuē wàn wù、hào ér dú zhī",meaning:"以万概称众物，号读涉及称说、指称。名称可用于交流，不等于已穷尽其所指。"},{id:"zy_discourse_yiyou",term:"已有之矣，乃将得比哉",pinyin:"yǐ yǒu zhī yǐ, nǎi jiāng dé bǐ zāi",meaning:"有、之、比的句法与所指有解释空间。联系前后可讨论称道是否足以比拟道，不只定为已经拥有一个名称。"},{id:"zy_discourse_wuqi",term:"恶起、桥起、片合、庸有",pinyin:"wū qǐ、qiáo qǐ、piàn hé、yōng yǒu",meaning:"恶在何处义读 wū；桥有起动等训释，片合与庸有涉及雌雄相合及生有。保留古代生成论语境，不转为现代科学说明。"},{id:"zy_discourse_ji",term:"可纪、可志、极物",pinyin:"kě jì、kě zhì、jí wù",meaning:"纪、志涉及记录、标识；极物联系穷至物的范围理解。不能因此说关于物的研究没有价值。"},{id:"zy_discourse_yizhi",term:"不随其所废，不原其所起",pinyin:"bù suí qí suǒ fèi, bù yuán qí suǒ qǐ",meaning:"原有推原、追溯义，句中代词所指与意义需辨。可保留对终极解释的限制，不直接禁止一切起源与历史研究。"},{id:"zy_discourse_huoshi",term:"或使、莫为",pinyin:"huò shǐ、mò wéi",meaning:"分别联系有主使者与无主使者的生成解释。莫为不直接等同个人什么都不做，也不与全篇所有无为用法混同。"},{id:"zy_discourse_wulun",term:"无伦、不可围",pinyin:"wú lún、bù kě wéi",meaning:"精微与广大超出比类、围括等，具体训释有空间。不作为数学或物理上的无限性证明。"},{id:"zy_discourse_jizu",term:"未生不可忌，已死不可阻",pinyin:"wèi shēng bù kě jì, yǐ sǐ bù kě zǔ",meaning:"忌、阻有抑止等训释。讨论死生及其说明限度，不用于否定医疗预防、救治与保护生命。"},{id:"zy_discourse_yanzhiwu",term:"无穷无止，言之无也",pinyin:"wú qióng wú zhǐ, yán zhī wú yě",meaning:"句法与无的所指有解释空间，联系本末推求及言说范围理解。不只定为语言本身无限。"},{id:"zy_discourse_you",term:"道不可有，有不可无",pinyin:"dào bù kě yǒu, yǒu bù kě wú",meaning:"道与有无的反常表述，有不同训释。不只用道无形所以不能存在解释，也不简单划成道不存在而万物存在。"},{id:"zy_discourse_jiaqu",term:"所假而行、一曲、大方",pinyin:"suǒ jiǎ ér xíng、yī qū、dà fāng",meaning:"假为借助；一曲为局部、偏向；大方涉及广大之道等。道名可借用，不证明自称框架外便自然全知。"},{id:"zy_discourse_yanmo",term:"物之极、言默不足以载、议有所极",pinyin:"wù zhī jí、yán mò bù zú yǐ zài、yì yǒu suǒ jí",meaning:"极涉及至极、极限等解释，载为承载。限制言默与议论的充分性，不等于所有言说错误，或沉默自动正确。"}];return(R,n)=>{const S=r("DaoReadingPrelude"),s=r("DaoTextReading"),d=r("DaoKeywordCards"),l=r("DaoLineGuide");return C(),V("div",null,[n[0]||(n[0]=i("",9)),a(S,{title:"先读前四段：交往、命名、从师与蜗角之争",summary:"则阳求见未成，王果转而描述公阅休及相通而保己的处身；第二段并置美、爱人与命名，第三段保留从师而不囿的线索，第四段以蜗角争战改变魏王观看报复的尺度。",points:[{label:"先看",text:"引荐为何没有完成？王果对夷节、公阅休与自己的评价是否构成固定高下？"},{label:"再问",text:"性、命名、师天与从师之间，怎样避免把所学变成圈限？"},{label:"最后",text:"蜗角之喻怎样反省报复？宏观尺度能否替代对具体伤害与责任的判断？"}],hint:"全篇十段均已整理：前四段立起求见、性与命名、从师与蜗角之争，五至八段转入陆沉者、治禾、辜人与蘧伯玉之化，九、十段收在名号与言默之限；文末脉络地图、三问、现代引申、索引与校读说明覆盖全篇。"}),n[1]||(n[1]=t("h2",{id:"一、则阳求见·引荐与相通而保己",tabindex:"-1"},[e("一、则阳求见·引荐与相通而保己 "),t("a",{class:"header-anchor",href:"#一、则阳求见·引荐与相通而保己","aria-label":'Permalink to "一、则阳求见·引荐与相通而保己"'},"​")],-1)),n[2]||(n[2]=t("h3",{id:"原文",tabindex:"-1"},[e("原文 "),t("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),a(s,{sections:p,glossary:o,"default-mode":"classic","aria-label":"则阳·求见楚王与公阅休 原文"}),n[3]||(n[3]=t("blockquote",null,[t("p",null,"**阅读说明：**王果先说不如公阅休，随后又说「吾又不若夷节」。不宜将三人排列成夷节、王果、公阅休逐级上升的贤者阶梯。"),t("p",null,"公阅休由王果描述，未直接参与本段对话；不直接出场不等于他没有实际生活与行为。")],-1)),n[4]||(n[4]=t("h3",{id:"生僻字词",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"谭",pinyin:["tán"],meaning:"谈及、介绍。"},{term:"戳",pinyin:["chuō"],meaning:"来稿字形，刺取、捕取义及异文待核。"},{term:"山樊",pinyin:["shān","fán"],meaning:"山边、山林边际等。"},{term:"暍",pinyin:["yē"],meaning:"暑热所困、中暑等。"},{term:"颠冥",pinyin:["diān","míng"],meaning:"昏惑、沉迷等。"},{term:"饮人",pinyin:["yìn","rén"],meaning:"使人饮，饮作使动。"}]}),n[5]||(n[5]=t("h3",{id:"核心句引读",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(l,{title:"所求尚未完成，先问交往怎样发生",subtitle:"保己与相通并列，不是远离所有人，也不是以关系换失自己。",lines:[{text:"夷节言之于王，王未之见。",tone:"未成",guide:"夷节已经进言，但尚未完成会见。不能补成夷节找不到王果，也不能据此认定求见永远不可能。故事让引荐的结果与交往者的处身同时成为问题。"},{text:"我不若公阅休……吾又不若夷节。",tone:"不若",guide:"王果的自评不能整理成王果比夷节更贤。不同不若可能涉及不同情境与能力，至少应保留原文关系，不以预设的境界等级替换。"},{text:"冬则戳鳖于江，夏则休乎山樊。",tone:"生活",guide:"公阅休有捕取与休息的生活，并非只凭不出现而发生作用。可以关注其生活不以宫廷为中心，但原文未明言他从不求见任何人，也未证明所有固定居所都构成执著。"},{text:"非相助以德，相助消也。",tone:"交往",guide:"把相互扶助与共同消损区分，批评被富贵牵引的交往。不能由此宣布推荐、合作、人际互助全部无价值。更具体的问题是交往是否让人更受所求役使。"},{text:"非夫佞人正德，其孰能桡焉。",tone:"疑难",guide:"佞人正德的组合不宜直接加或字拆成两类人，也不能据此补出则阳既非巧言者又非正德者。暂保留对严厉楚王如何被改变的追问，具体译法待底本核对。"},{text:"乐物之通而保己焉。",tone:"相通与保己",guide:"相通与保己并列，既不是彻底封闭，也不是为了关系放弃自身。现代可以联系有边界的交往，却不把古文直接等同现代心理学术语。"},{text:"不言而饮人以和，与人并立而使人化。",tone:"和与化",guide:"写感化不完全依靠口头说进，不能补成神秘气场，也不证明人物只要存在就让所有人自动改变。理想化描述不替代沟通、照料与具体条件。"}]}),n[6]||(n[6]=i("",12)),a(s,{sections:h,glossary:u,"default-mode":"classic","aria-label":"则阳·性与命名 原文"}),n[7]||(n[7]=t("blockquote",null,[t("p",null,"**阅读说明：**本段反常表达较密集。「一不化者」「未始有天」「不洫」等不强定唯一解释。"),t("p",null,"美与爱人的类比，重点可放在实际表现与命名的区别，不据此宣布不了解自己必然更美、更有德。")],-1)),n[8]||(n[8]=t("h3",{id:"生僻字词-1",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"绸缪",pinyin:["chóu","móu"],meaning:"交结、深微关系等。"},{term:"鉴",pinyin:["jiàn"],meaning:"镜、镜鉴。"},{term:"缗",pinyin:["mín"],meaning:"本句有遮蔽、混合等解释。"},{term:"县",pinyin:["xuán"],meaning:"联系悬理解。"},{term:"环中",pinyin:["huán","zhōng"],meaning:"可与道枢之论对读。"},{term:"殉",pinyin:["xùn"],meaning:"逐物、为物所牵等。"},{term:"洫",pinyin:["xù"],meaning:"本句有损耗等解释。"}]}),n[9]||(n[9]=t("h3",{id:"核心句引读-1",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(l,{title:"被称为爱人，不是爱人行为的唯一来源",subtitle:"反省命名和对象化，不意味着取消认识与学习。",lines:[{text:"而不知其然，性也。",tone:"性",guide:"以性说明所行未必来自逐步计算与自我命名。不能把不知其然扩成完全不需理解原因、知识普遍有害。熟练、自然与经过学习也不必互相排斥。"},{text:"生而美者，人与之鉴。",tone:"镜与评价",guide:"他人给出镜鉴，帮助形成对自身的认识。类比并未证明镜子有害，也不要求拒绝他人反馈；它区分表现本身与对表现的意识。"},{text:"圣人之爱人也，人与之名。",tone:"爱与名",guide:"爱人与爱人的名称并置：实际相处不必依赖先占有一个称号。不能据此说只要自知正在关怀，就已不是真关怀。知情的照料与责任同样可以有价值。"},{text:"其爱人也终无已，人之安之亦无已。",tone:"持续",guide:"理想化地写爱人与人安于之的持续，不应转成爱人者必获所有人认可的保证。也不把圣人的爱解释为必须无边界地承受任何要求。"},{text:"旧国旧都，望之畅然。",tone:"熟悉与感受",guide:"故国旧都虽有遮蔽变化，仍引发感受。后文句法有疑难，不能仅据此证明本源始终不变，也不将所有人的故地感受统一规定为欢畅。"},{text:"日与物化者，一不化者也。",tone:"化与不化",guide:"在相与变化中说不化，形成值得辨析的反常命题。一的用法与所指未必是独立实体，不能直接画成外表变化、体内永恒本体的两层结构。"},{text:"夫师天而不得师天，与物皆殉。",tone:"师天",guide:"师天也可能成为被追逐的对象，提醒原则与实际处身未必一致。不能建立凡有意学习便必然失败的规律，也不要求取消所有目标与方法。"},{text:"未始有天……未始有物，与世偕行而不替。",tone:"不固定与偕行",guide:"限制天人物始的固定区分，同时仍说与世偕行。不是退出现实，也不只是脑中没有相关词汇。可以保留不把分别绝对化与继续应接并存的方向。"}]}),n[10]||(n[10]=i("",8)),a(s,{sections:g,glossary:y,"default-mode":"classic","aria-label":"则阳·从师而不囿 原文"}),n[11]||(n[11]=t("blockquote",null,[t("p",null,"**校读说明：**本段中部文字、句读及人物关系难以确定，暂保留来稿，不强行逐字译通。"),t("p",null,"来稿称多位注家均指出脱简、错讹；在核对各家原注前，不将这一归纳作为已确认的注家意见。")],-1)),n[12]||(n[12]=t("h3",{id:"生僻字词-2",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"司御",pinyin:["sī","yù"],meaning:"涉及御者、职掌等，具体关系待校。"},{term:"傅",pinyin:["fù"],meaning:"辅导、师傅等。"},{term:"囿",pinyin:["yòu"],meaning:"圈限、局限。"},{term:"嬴",pinyin:["yíng"],meaning:"本句字形与意义待校。"},{term:"容成氏",pinyin:["róng","chéng","shì"],meaning:"古代传说人物。"}]}),n[13]||(n[13]=t("h3",{id:"核心句引读-2",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(l,{title:"从师与不囿，可以同时成立",subtitle:"保留可辨线索，不用完整哲学故事填补疑难原文。",lines:[{text:"从师而不囿，得其随成。",tone:"学习",guide:"从师与不被圈限并列，不能只留下不囿而删除学习。可以理解为受教不必等于照搬，也不能由此说无需训练、任何规范都会损害本性。"},{text:"为之司其名之名嬴法得其两见。",tone:"存疑",guide:"不确定句读、字形与所指时，保留疑难比补造官职和法度理论更稳妥。本页不把名之名、嬴法、两见分别解释成已坐实的概念系统。"},{text:"仲尼之尽虑，为之傅之。",tone:"关系待辨",guide:"与前文关系尚需校读，不直接补成孔子穷尽思考后由这件事受教，也不据此证明某种理论已高于孔子的全部认识。"},{text:"除日无岁，无内无外。",tone:"关系",guide:"可以讨论日与岁、内与外的相依关系，但不能短接为所有整体都虚假、只有部分真实。日也具有计量与命名层面，年亦可对应实际周期，不能简单分成日真实、岁虚设。"}]}),n[14]||(n[14]=i("",5)),a(s,{sections:m,glossary:b,"default-mode":"classic","aria-label":"则阳·蜗角之争 原文"}),n[15]||(n[15]=t("blockquote",null,[t("p",null,"**阅读说明：**蜗角两国是寓言，不是现实中存在蜗牛角国家的事实论证。"),t("p",null,"君王赞戴晋人为大人，是人物评价；若有所失也不能直接认定为已完全放弃报复。")],-1)),n[16]||(n[16]=t("h3",{id:"生僻字词-3",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"万乘",pinyin:["wàn","shèng"],meaning:"大国君主之称，乘读 shèng。"},{term:"抶",pinyin:["chì"],meaning:"击打。"},{term:"胥靡",pinyin:["xū","mí"],meaning:"服役、受刑役者等。"},{term:"逐北",pinyin:["zhú","běi"],meaning:"追逐败逃者。"},{term:"旬有五日",pinyin:["xún","yòu","wǔ","rì"],meaning:"十五日，有联系又理解。"},{term:"惝然",pinyin:["chǎng","rán"],meaning:"怅惘、失神。"},{term:"吷",pinyin:["xuè"],meaning:"微小的声音。"}]}),n[17]||(n[17]=t("h3",{id:"核心句引读-3",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(l,{title:"从报复的中心退出一步，不等于取消具体责任",subtitle:"尺度转换可以改变执着，不能把伤亡解释成没有意义。",lines:[{text:"魏莹怒，将使人剌之。",tone:"行动起点",guide:"报复从君主因背约而怒起，后续进言不断改变手段与理由。背约需要辨明，但愤怒本身不能自动证明刺杀或大规模战争正当。"},{text:"虏其人民，系其牛马……然后拔其国。",tone:"升级",guide:"公孙衍将私仇升级为动员、俘虏与攻拔，原文清楚涉及人民与资源代价。不能只称之为更堂正的报仇方式而忽略被卷入者。"},{text:"今兵不起七年矣，此王之基也。",tone:"休兵",guide:"季子明确指出休兵积累的基础与筑而复坏的劳苦。后文华子的批评不自动抹掉这些现实差异，也不证明战争与不战后果一样。"},{text:"谓伐之与不伐乱人也者，又乱人也。",tone:"递归",guide:"不仅评判主战主和，也回看评判者本身，可与《徐无鬼》悲的递归对读。但不能将所有不同层次的意见机械判为同一种执著，也不把第三层立成新的绝对正确位置。"},{text:"君求其道而已矣。",tone:"转向",guide:"从选边争胜转向求其道，是故事的方向。不能仅译成永远不选战和、无需作实际决定；现实行动仍需面对风险、保护与后果。"},{text:"时相与争地而战，伏尸数万。",tone:"蜗角",guide:"极小空间与巨大伤亡并置，使君主熟悉的争地逻辑变得陌生。讽刺争夺尺度，不等于嘲笑受害者，也不意味着死亡在宇宙中小便不值得重视。"},{text:"通达之中有魏，于魏中有梁，于梁中有王。",tone:"反观",guide:"把君王从观看中心变成层层范围中的一部分，松开自我重要性的绝对感。它是对话中的视角转换，不是已完成的宇宙无限性科学证明。"},{text:"王与蛮氏有辩乎？",tone:"比较",guide:"在所引入的尺度上比较君王与蜗角争夺者。不能据此否认现实政治、历史处境和伦理责任的所有区别。宏观相似与具体差异可以同时成立。"},{text:"君惝然若有亡也。",tone:"反应",guide:"若有所失明确写出震动，却未指明所失为何。可以说原有观看方式被动摇，不直接补成报复心已经完全消失或君主此后不再兴兵。"},{text:"道尧、舜于戴晋人之前，譬犹一吷也。",tone:"称誉的尺度",guide:"惠子以微声限制尧舜之誉在戴晋人面前的分量。不是说声音越短越接近本质，也不能从人物赞誉建立戴晋人高于所有圣人的固定等级。"}]}),n[18]||(n[18]=i("",22)),a(s,{sections:c,glossary:_,"default-mode":"classic","aria-label":"则阳·孔子与陆沉者 原文"}),n[19]||(n[19]=t("blockquote",null,[t("p",null,"**整理说明：**本段依据来稿中的分散引文重排。登极、圣人仆、著于己等保留训释空间。"),t("p",null,"「是其市南宜僚邪」是身份推测，不能直接改成已经确认。善卷拒舜出自《让王》，不属于《徐无鬼》。")],-1)),n[20]||(n[20]=t("h3",{id:"生僻字词-4",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"舍",pinyin:["shè"],meaning:"投宿。"},{term:"浆",pinyin:["jiāng"],meaning:"浆饮，句中可联系卖浆者及其处所。"},{term:"稯稯",pinyin:["zōng","zōng"],meaning:"聚集等状态。"},{term:"销",pinyin:["xiāo"],meaning:"消隐。"},{term:"陆沉",pinyin:["lù","chén"],meaning:"在陆而沉，借写处世隐没。"},{term:"佞",pinyin:["nìng"],meaning:"巧言、说进等，依语境理解。"}]}),n[21]||(n[21]=t("h3",{id:"核心句引读-4",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(l,{title:"看见对方，不等于有权让对方进入自己的安排",subtitle:"孔子的推测与空室的结局，需要区分。",lines:[{text:"其邻有夫妻臣妾登极者。",tone:"所见",guide:"邻人的活动是子路提问的起点，登极的具体所指有解释空间。不能补成全家一起登屋劳作或避暑，再把所补情节当成原文事实。"},{text:"自埋于民，自藏于畔。",tone:"隐没",guide:"隐没可以发生于民众生活之中，不只靠远离人群。但不能由此建立在人群中隐居必高于山林隐居的等级，也不要求人人抹去身份。"},{text:"其口虽言，其心未尝言。",tone:"言与心",guide:"说话与心不受言说牵引可作对读，不仅是隐藏秘密。不能把它变成从不表达需求、拒绝真实沟通的要求。"},{text:"是其市南宜僚邪？",tone:"推测",guide:"名称与《徐无鬼》互见值得比较，但孔子的疑问不等于已证身份。也不能复原成宜僚已在幕后完成精确预判。"},{text:"以丘为必使楚王之召己也。",tone:"召见",guide:"孔子推测对方会把自己的到来与楚王召见联系起来。可以反省举荐是否符合当事人意愿，不必宣布所有游说、引荐都等同谄媚。"},{text:"子路往视之，其室虚矣。",tone:"空室",guide:"空室是明确结局，离去的时间、过程与全部动机没有直接叙述。可以说没有形成会面，不宜补成对方早已精确洞察孔子全部意图。"}]}),n[22]||(n[22]=i("",10)),a(s,{sections:z,glossary:x,"default-mode":"classic","aria-label":"则阳·封人治禾与治形理心 原文"}),n[23]||(n[23]=t("blockquote",null,[t("p",null,"**阅读说明：**本段从改进耕作转入身心，肯定深耕熟耰，不能概括为一切人为方法都有害。"),t("p",null,"末尾疮病与溲膏属于古代病象及论述语境，不作为现代诊断、病因证明或治疗建议。")],-1)),n[24]||(n[24]=t("h3",{id:"生僻字词-5",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-5","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"卤莽",pinyin:["lǔ","mǎng"],meaning:"粗疏草率。"},{term:"灭裂",pinyin:["miè","liè"],meaning:"马虎、不周等。"},{term:"芸",pinyin:["yún"],meaning:"联系耘、除草理解。"},{term:"耰",pinyin:["yōu"],meaning:"耙土、覆土等耕作。"},{term:"飧",pinyin:["sūn"],meaning:"饭食。"},{term:"萑",pinyin:["huán"],meaning:"芦苇类植物。"},{term:"擢",pinyin:["zhuó"],meaning:"拔、抽引等，句中意义待辨。"},{term:"癕",pinyin:["yōng"],meaning:"联系痈理解。"}]}),n[25]||(n[25]=t("h3",{id:"核心句引读-5",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(l,{title:"不是不照料，而是辨明怎样照料",subtitle:"方法多不等于适宜，随顺也不等于任其荒废。",lines:[{text:"君为政焉勿卤莽，治民焉勿灭裂。",tone:"不草率",guide:"直接提出为政治民不应粗疏，说明本篇并非只要求停止一切治理。判断、照料与认真执行仍有位置。"},{text:"深其耕而熟耰之，其禾蘩以滋。",tone:"改进",guide:"改变方法、细致耕作获得更好结果，是明确的实践线索。不能说自然成就完全排除学习、试验与有意改进。故事也不构成任何农法无条件成功的保证。"},{text:"遁其天，离其性，灭其情，亡其神，以众为。",tone:"损害",guide:"并列描写身心受损与施为的关系，批评不适宜的处身。不能把四句自动列为损害等级，也不能由众为推出所有教育、训练、心理支持或医疗干预都有害。"},{text:"欲恶之孽为性。",tone:"欲恶",guide:"欲恶、孽、为性的关系需辨，可以反省欲恶滋生如何改变处身。不能先设定人本无任何欲望或厌恶，再说这些都来自外在污染。"},{text:"萑苇蒹葭始萌，以扶吾形，寻擢吾性。",tone:"耕作譬喻",guide:"植物意象接续治禾经验，但扶、擢的具体意义不宜一概坐实。可以看见杂生与身心的比喻，不必建成现代生理侵蚀模型。"},{text:"漂疽疥癕，内热溲膏是也。",tone:"古代病象",guide:"身体性描写使损害更具体，但不能用来判定现代疾病源自欲恶、失德或违逆本性。现实症状应由医疗专业评估，不因哲学解释延误诊疗。"}]}),n[26]||(n[26]=i("",6)),a(s,{sections:q,glossary:f,"default-mode":"classic","aria-label":"则阳·柏矩见辜人与责任追问 原文"}),n[27]||(n[27]=t("blockquote",null,[t("p",null,"**阅读说明：**辜人的具体刑式、失其形的意义等保留说明。故事将个体遭难放入治理条件中考察。"),t("p",null,"追问制度责任不等于免除行为者的一切责任，也不把贫困与欺盗建立成无例外的因果。")],-1)),n[28]||(n[28]=t("h3",{id:"生僻字词-6",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-6","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"辜人",pinyin:["gū","rén"],meaning:"受罪刑、遭刑而陈尸者等。"},{term:"幕",pinyin:["mù"],meaning:"覆盖。"},{term:"号天",pinyin:["háo","tiān"],meaning:"向天哭号。"},{term:"离",pinyin:["lí"],meaning:"本句联系罹、遭遇理解。"},{term:"枉",pinyin:["wǎng"],meaning:"枉曲、失正。"},{term:"不胜",pinyin:["bù","shèng"],meaning:"不能承受、胜任。"},{term:"涂",pinyin:["tú"],meaning:"联系途、道路理解。"}]}),n[29]||(n[29]=t("h3",{id:"核心句引读-6",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-6","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(l,{title:"责罚未达要求者之前，先检查要求与条件",subtitle:"看见个体行为，也看见使行为发生的治理环境。",lines:[{text:"天下犹是也。",tone:"天下处境",guide:"老聃说天下仍如此，可读作对现状的提示。不能直接推成所有地方毫无差别、游历不能提供知识。柏矩随后仍实际前往齐国。"},{text:"解朝服而幕之，号天而哭之。",tone:"哀悼",guide:"覆盖与哭号让遭刑者重新成为值得悲悯的人。不能只将其称为最卑贱者，也不必补出具体案情、刑式或证明他没有实施任何伤害。"},{text:"天下有大灾，子独先离之。",tone:"个体与天下",guide:"把一个人的遭难置于更广的天下处境。可以关注结构条件，不等于同样环境中的任何人必有同一结局，也不应抹掉这位死者的具体遭遇。"},{text:"荣辱立然后睹所病，货财聚然后睹所争。",tone:"病与争",guide:"将标准与财货聚积同病苦、争夺相接，力度鲜明。不能补成所有荣辱制度都出于善意，也不能据此否定任何规则、资源储备与财产安排。需要检查具体设置如何产生压力与争夺。"},{text:"以得为在民，以失为在己。",tone:"治理者自责",guide:"以古代君人者的理想形象反衬当前责罚方式，不一定是已经证实的普遍古代史。责任方向从只责民转到为政者检查自身。"},{text:"重为任而罚不胜，远其涂而诛不至。",tone:"要求与条件",guide:"加重负担、拉远目标，却惩罚不能承受、不能到达，构成尖锐批评。应检查要求与资源是否相称，不必补成每项要求都出于蓄意陷害。"},{text:"民知力竭，则以伪继之。",tone:"耗竭",guide:"在知力耗尽后以伪应付，指出评价与负担可能催生失真。不是说明每个受压者都会欺骗，也不是将欺骗自动正当化。"},{text:"盗窃之行，于谁责而可乎？",tone:"归责",guide:"追问归责是否只落在行为者身上，要求纳入治理条件。不能删掉犯罪的受害者，也不必只选制度或个人中的一方。理解成因、追究责任与防止再次伤害，可以同时进行。"}]}),n[30]||(n[30]=i("",12)),a(s,{sections:k,glossary:P,"default-mode":"classic","aria-label":"则阳·蘧伯玉六十化 原文"}),n[31]||(n[31]=t("blockquote",null,[t("p",null,"**阅读说明：**六十化写不断改变与回看，不作为每年必推翻上一年全部观点的精确记录。"),t("p",null,"末句「然与然」及其语气保留解释空间，不强定为绝望、释然或终极相对主义。")],-1)),n[32]||(n[32]=t("h3",{id:"生僻字词-7",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-7","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"蘧伯玉",pinyin:["qú","bó","yù"],meaning:"古代人物，本段借其写认识修正。"},{term:"诎",pinyin:["qū"],meaning:"联系屈，屈退、否定等。"},{term:"卒",pinyin:["zú"],meaning:"最终。"},{term:"恃",pinyin:["shì"],meaning:"依赖。"},{term:"大疑",pinyin:["dà","yí"],meaning:"重大的疑问、疑惑。"}]}),n[33]||(n[33]=t("h3",{id:"核心句引读-7",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-7","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(l,{title:"当前判断可以使用，也需要留下修正的余地",subtitle:"承认所不知，不等于放弃扩展所知。",lines:[{text:"行年六十而六十化。",tone:"变化",guide:"以六十化强调持续变化，不必复原为一至六十年的观点清单。变化也不都只是知识错误，还可能涉及处境、理解与实践的调整。"},{text:"未尝不始于是之，而卒诎之以非也。",tone:"回看",guide:"曾经自认正确的判断后来受到否定，限制当下自信。不能由一个人物的叙述推出每项可靠知识都必定被推翻，也不要求每次修正必须全盘否定此前所得。"},{text:"未知今之所谓是之非五十九非也。",tone:"今之是",guide:"句法有讨论空间，重点可放在当前所是仍需审视。不能预报它必是下一次错误；保留可修正性与当前理由较充分，可以同时成立。"},{text:"有乎生而莫见其根，有乎出而莫见其门。",tone:"根与门",guide:"所见现象未穷尽其来源，提醒认识范围。不等于任何来源都永不可研究，当前未见与原则上无法认识应区分。"},{text:"恃其知之所不知而后知。",tone:"认识条件",guide:"认识可能依赖尚未被认识的条件与范围，可引申为不把已知认成全部。不能只译成承认不知便获得真知，也不能说扩大知识边界没有价值。"},{text:"已乎！已乎！且无所逃。",tone:"感叹",guide:"反复感叹与无所逃并置，具体情绪与所逃对象不宜强定。不必写成彻底绝望，也不必补成看透以后已经安然释怀。"},{text:"此所谓然与然乎！",tone:"末句存疑",guide:"然与然的关系及句式需要依注本辨析。可以保留对然、是的追问，不将它直接证明为没有任何可共同检验的判断。"}]}),n[34]||(n[34]=i("",35)),a(s,{sections:w,glossary:T,"default-mode":"classic","aria-label":"则阳·卫灵公之灵 原文"}),n[35]||(n[35]=t("blockquote",null,[t("p",null,"**整理说明：**本段依据来稿分散引文重排。"),t("p",null,"三个回答代表不同解释方式，不直接排成由浅入深、最后获得真理的阶梯。古墓铭文按神异叙事阅读，不验证占卜、预言与命定。")],-1)),n[36]||(n[36]=t("h3",{id:"生僻字词-8",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-8","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"大史",pinyin:["tài","shǐ"],meaning:"联系太史理解。"},{term:"大弢",pinyin:["dà","tāo"],meaning:"篇中人物。"},{term:"狶韦",pinyin:["xī","wéi"],meaning:"篇中人物，身份不在此坐实。"},{term:"弋",pinyin:["yì"],meaning:"系绳之箭射取。"},{term:"槨",pinyin:["guǒ"],meaning:"棺外套具。"},{term:"冯",pinyin:["píng"],meaning:"联系凭、依恃理解。"}]}),n[37]||(n[37]=t("h3",{id:"核心句引读-8",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-8","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(l,{title:"同一个名号，可以进入不同的解释框架",subtitle:"不同回答并置，不等于最后的神异故事已证明命定。",lines:[{text:"其所以为灵公者何邪？",tone:"名与行",guide:"将灵公之名与所列行为相接，追问名称怎样成立。灵有多种谥义，不能先规定为美谥，再判断行为必然与名称冲突。"},{text:"是因是也。",tone:"第一答",guide:"可以联系正因为如此，所以称灵等理解，未必答非所问。简短不等于浅薄，暂不以现代循环论证标签替代训释。"},{text:"其慢若彼之甚也，见贤人若此其肃也。",tone:"第二答",guide:"将放纵与见贤敬肃并置，使人物不能只用一种行为概括。慢不直接等于怠慢妻子，也不能仅凭敬贤便取消荒政责任。"},{text:"不冯其子，灵公夺而里之。",tone:"第三答",guide:"铭文使解释转入神异叙事，所指与句法仍需辨析。不能从故事推出一切命运早已预定，也不补定铭文一定早于灵公出生。"},{text:"之二人何足以识之。",tone:"人物评价",guide:"狶韦贬评前两人的解释，是人物之言。不能直接据此认定作者已排出三层知识等级，或最后一答就是唯一答案。"}]}),n[38]||(n[38]=i("",8)),a(s,{sections:j,glossary:v,"default-mode":"classic","aria-label":"则阳·少知问大公调 原文"}),n[39]||(n[39]=t("blockquote",null,[t("p",null,"**阅读说明：**本段内部较长，按问答拆为十个阅读单元，不改变本项目第十段编号。"),t("p",null,"丘里、生成关系、或使莫为与篇末言默之限，不能只压缩成所有语言无用。大公调仍通过持续说明限制说明本身。")],-1)),n[40]||(n[40]=t("h3",{id:"生僻字词-9",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-9","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"丘里",pinyin:["qiū","lǐ"],meaning:"乡里、乡邑。"},{term:"距",pinyin:["jù"],meaning:"联系拒理解。"},{term:"殊",pinyin:["shū"],meaning:"不同。"},{term:"恶起",pinyin:["wū","qǐ"],meaning:"从何处起，恶读 wū。"},{term:"纪、志",pinyin:["jì","zhì"],meaning:"记录、标识等。"},{term:"原",pinyin:["yuán"],meaning:"推原、追溯。"},{term:"一曲",pinyin:["yī","qū"],meaning:"局部、偏向。"},{term:"载",pinyin:["zài"],meaning:"承载。"}]}),n[41]||(n[41]=t("h3",{id:"核心句引读-9",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-9","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(l,{title:"共同性不必消灭差异，名称也不等于占有所指",subtitle:"或使、莫为与言默，都不能自动保证已经穷尽道。",lines:[{text:"合异以为同，散同以为异。",tone:"同与异",guide:"从共同体看见共同，从组成者看见差异。不能把同定为绝对一致，也不把异定为完全隔绝。共同生活与差异可以并存。"},{text:"指马之百体而不得马。",tone:"部分与整体",guide:"逐指各部不等于已经把握马，提醒部分、联系与整体的区别。不证明马只是虚假名称，也不否定研究各部的价值。"},{text:"有主而不执；有正而不距。",tone:"不执不拒",guide:"有所主、正，仍不执、不拒，保留方向与开放并存。不能要求没有判断，也不把开放理解为接受全部侵害或错误。"},{text:"万物殊理，道不私。",tone:"殊与公",guide:"反复强调殊，不私并非将万物变成一样。可以反省单一尺度垄断，但不直接作为任何现代制度都已被证明的依据。"},{text:"无名故无为，无为而无不为。",tone:"无为语境",guide:"放在殊而不私的语境中，可理解为不以偏执施为覆盖不同者。不是全不行动，也不是现实中能够完成任何事情的无限能力。"},{text:"然则谓之道足乎？……不然。",tone:"再追问",guide:"已经说到共同、差异与无为，仍不宣布这套说明就是道的全部。不能因此说前面说明毫无价值，而应区别有用与充分。"},{text:"以数之多者号而读之也。",tone:"名称",guide:"万物之万是概称，不是精确计数。名称可以帮助交流，不保证逐一覆盖所指，也不意味着名称皆虚假。"},{text:"此名实之可纪，精之可志也。",tone:"可记录",guide:"承认有可记录、可标识的生成关系，不能只留下言知受限而删除观察的价值。古代生成论与现代科学仍需区分。"},{text:"此议之所止。",tone:"议论边界",guide:"限制以当前说明穷尽终极根源的企图，不直接禁止起源研究、历史探究或继续求证。标明不确定，仍可以研究。"},{text:"或之使，莫之为，未免于物。",tone:"两家",guide:"对有主使与无主使的解释均提出限制，不必选一方为已经证明的终极答案。也不能简化为所有因果分析都错误。"},{text:"道之为名，所假而行。",tone:"道名",guide:"道名也被纳入借助性，提醒不把名称等同所指。不能将假借理解为随意编造，或宣称不用道字便自然得道。"},{text:"或使莫为，在物一曲。",tone:"局部",guide:"局部解释不能自动穷尽广大之道，但局部不等于无用。可在适用范围内保留说明，不把范围限制变成全盘否定。"},{text:"言默不足以载。",tone:"言与默",guide:"同时限制言说与沉默，不能整理成越少说越正确。解释、沟通与保持沉默，都需要面对具体处境。"},{text:"非言非默，议有所极。",tone:"篇末",guide:"不把言或默立成最后的占有方式。承认议论有限，不是禁止全部讨论，也不是宣布已经找到一种无需检验的神秘第三方式。"}]}),n[42]||(n[42]=i("",116))])}}});export{E as __pageData,G as default};
